import xarray as xr
import numpy as np
from xarray.core.indexes import Index
from xarray.core.variable import Variable

class CustomIndex(Index):
    def __init__(self, coords, options=None):
        self.coords = coords

    @classmethod
    def from_variables(cls, variables, options=None):
        # Use the first variable's values as the index data
        first_var = list(variables.values())[0]
        return cls(first_var.values)

    def create_variables(self, variables=None):
        # Return the original variables plus a new one
        res = dict(variables) if variables else {}
        # Create a new variable 'extra_coord'
        # In a real scenario, this would be based on the index data
        # For this repro, we just create a dummy variable
        res['extra_coord'] = Variable('x', np.array([1, 2, 3]), attrs={'attr': 'extra'})
